changeSet.sql:
INSERT INTO plugins (
identifier, name, description,
javascriptModuleFile,
functionsViewTemplate,
settingsViewTemplate,
namelocalizationkey,
settingsPermission, functionsPermission, deviceFunctionsPermission,
enabledForDevice
)
VALUES (
'remotesupport', 'Remote Support', 'Remote view and control of devices',
'app/components/plugins/remotesupport/remotesupport.module.js',
'app/components/plugins/remotesupport/views/remotesupport.html',
NULL,
'plugin.remotesupport.localization.key.name',
NULL,
'plugin_remotesupport_view',
'plugin_remotesupport_view',
TRUE
);

-- Permissions are granted to the administrator roles only; assign them to other roles explicitly
INSERT INTO permissions (name, description) VALUES ('plugin_remotesupport_view', 'Can view device screens remotely');
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (1, currval('permissions_id_seq'));
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (2, currval('permissions_id_seq'));
INSERT INTO permissions (name, description) VALUES ('plugin_remotesupport_control', 'Can control devices remotely');
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (1, currval('permissions_id_seq'));
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (2, currval('permissions_id_seq'));
INSERT INTO permissions (name, description) VALUES ('plugin_remotesupport_settings', 'Can enable remote support for configurations');
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (1, currval('permissions_id_seq'));
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (2, currval('permissions_id_seq'));

-- Remote support is off for every configuration until an administrator turns it on
CREATE TABLE plugin_remotesupport_settings (
    configurationId INT NOT NULL CONSTRAINT plugin_remotesupport_settings_pr_key PRIMARY KEY
        REFERENCES configurations (id) ON DELETE CASCADE,
    enabled BOOLEAN NOT NULL DEFAULT FALSE,
    requireAcceptance BOOLEAN NOT NULL DEFAULT TRUE,
    maxMinutes INT NOT NULL DEFAULT 60
);

CREATE TABLE plugin_remotesupport_sessions (
    id VARCHAR(36) NOT NULL CONSTRAINT plugin_remotesupport_sessions_pr_key PRIMARY KEY,
    deviceId INT NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    customerId INT NOT NULL,
    userId INT,
    userLogin VARCHAR(100),
    viewOnly BOOLEAN NOT NULL,
    createdAt BIGINT NOT NULL,
    connectedAt BIGINT,
    endedAt BIGINT,
    endReason VARCHAR(100),
    frames BIGINT NOT NULL DEFAULT 0,
    bytes BIGINT NOT NULL DEFAULT 0
);
CREATE INDEX plugin_remotesupport_sessions_device_idx ON plugin_remotesupport_sessions (deviceId, createdAt);

changeSet.rollback:
DELETE FROM plugins WHERE identifier = 'remotesupport';
DELETE FROM permissions WHERE name = 'plugin_remotesupport_view';
DELETE FROM permissions WHERE name = 'plugin_remotesupport_control';
DELETE FROM permissions WHERE name = 'plugin_remotesupport_settings';
DROP TABLE plugin_remotesupport_sessions;
DROP TABLE plugin_remotesupport_settings;

changeSet.sql:
ALTER TABLE plugin_remotesupport_settings ADD COLUMN IF NOT EXISTS transport VARCHAR(16) NOT NULL DEFAULT 'auto';
ALTER TABLE plugin_remotesupport_settings ADD COLUMN IF NOT EXISTS stunUrl VARCHAR(256);
ALTER TABLE plugin_remotesupport_settings ADD COLUMN IF NOT EXISTS turnUrl VARCHAR(256);
ALTER TABLE plugin_remotesupport_settings ADD COLUMN IF NOT EXISTS turnUsername VARCHAR(128);
ALTER TABLE plugin_remotesupport_settings ADD COLUMN IF NOT EXISTS turnCredential VARCHAR(256);

changeSet.rollback:
ALTER TABLE plugin_remotesupport_settings DROP COLUMN IF EXISTS turnCredential;
ALTER TABLE plugin_remotesupport_settings DROP COLUMN IF EXISTS turnUsername;
ALTER TABLE plugin_remotesupport_settings DROP COLUMN IF EXISTS turnUrl;
ALTER TABLE plugin_remotesupport_settings DROP COLUMN IF EXISTS stunUrl;
ALTER TABLE plugin_remotesupport_settings DROP COLUMN IF EXISTS transport;
